        COALESCE(NULLIF(TRIM(g.title_en), ''), g.title_fi) as display_name,

        COALESCE(NULLIF(TRIM(g.description_en), ''), g.description_fi) as description,

        f.funder_id,
        g.funder_project_number as funder_award_id,

